"""Tests for cynthus.messaging.common.signal.payload (SignalPayload)."""

# Generated by tools/generate_messaging_core_tests.py - edit the generator, not this file.

from datetime import datetime, timedelta, timezone

import pytest
from pydantic import ValidationError

from cynthus.messaging.common.signal.part import SignalPart
from cynthus.messaging.common.signal.payload import SignalPayload


def test_is_a_signal_part():
    assert issubclass(SignalPayload, SignalPart)


def test_schema_version_is_required():
    with pytest.raises(ValidationError):
        SignalPayload()


@pytest.mark.parametrize('version', [0, -1])
def test_schema_version_must_be_at_least_one(version):
    with pytest.raises(ValidationError):
        SignalPayload(schema_version=version)


def test_schema_version_must_be_an_integer():
    with pytest.raises(ValidationError):
        SignalPayload(schema_version='latest')


def test_observed_at_defaults_to_now_in_utc():
    before = datetime.now(timezone.utc)
    observed = SignalPayload(schema_version=1).observed_at

    assert observed.utcoffset() == timedelta(0)
    assert before <= observed <= datetime.now(timezone.utc)


def test_metadata_defaults_to_an_independent_empty_mapping():
    first, second = SignalPayload(schema_version=1), SignalPayload(schema_version=1)

    assert first.metadata == {} and first.metadata is not second.metadata


def test_metadata_accepts_structured_telemetry():
    payload = SignalPayload(schema_version=1, metadata={'execution_ms': 12, 'retry_count': 0})

    assert payload.metadata == {'execution_ms': 12, 'retry_count': 0}


def test_metadata_may_be_none():
    assert SignalPayload(schema_version=1, metadata=None).metadata is None


def test_observed_at_is_serialized_as_utc_iso_8601():
    local = datetime(2026, 7, 1, 20, 30, tzinfo=timezone(timedelta(hours=2)))

    wire = SignalPayload(schema_version=1, observed_at=local).model_dump(mode='json')

    assert wire['observed_at'] == '2026-07-01T18:30:00+00:00'


def test_payload_is_immutable():
    payload = SignalPayload(schema_version=1)

    with pytest.raises(ValidationError):
        payload.schema_version = 2
